// swift-tools-version: 6.0
import PackageDescription

// The app itself (Live Activity host + widget extension) is built by ClaudeNotch.xcodeproj, generated by
// scripts/gen_xcodeproj.py, because ActivityKit on macOS needs the macOS 27.3 SDK and a widget extension.
// SwiftPM builds and tests everything that is pure logic.
let package = Package(
    name: "claude-notch",
    platforms: [.macOS(.v14)],
    products: [
        .library(name: "ClaudeNotchCore", targets: ["ClaudeNotchCore"]),
        .executable(name: "claude-notch-hook", targets: ["claude-notch-hook"]),
    ],
    targets: [
        .target(name: "ClaudeNotchCore"),
        .executableTarget(name: "claude-notch-hook", dependencies: ["ClaudeNotchCore"]),
        .testTarget(name: "ClaudeNotchCoreTests", dependencies: ["ClaudeNotchCore"]),
    ]
)
